import hashlib,rbd

def _validate(cluster,image,owner,address):
    if not isinstance(owner,str)or not owner or owner!=address:
        raise ValueError('old owner/address must match the observed exact old session')
    owners=list(image.lock_get_owners())
    if len(owners)!=1 or owners[0]['mode']!=rbd.RBD_LOCK_MODE_EXCLUSIVE:
        raise ValueError('one proved managed exclusive owner is required')
    current=owners[0]['owner']
    if current not in (owner,cluster.get_addrs()):
        raise ValueError('observed old owner changed; stop and recollect evidence')
    return current==cluster.get_addrs()

def _report(cluster,image):
    size=image.size()
    return {'owner':cluster.get_addrs(),'bytes':size,'sha256':hashlib.sha256(image.read(0,size)).hexdigest()}

def takeover(cluster,image,owner,address):
    already_current=_validate(cluster,image,owner,address)
    if already_current:
        return _report(cluster,image)
    cluster.blocklist_add(address,60)
    cluster.wait_for_latest_osdmap()
    image.lock_break(rbd.RBD_LOCK_MODE_EXCLUSIVE,owner)
    image.lock_acquire(rbd.RBD_LOCK_MODE_EXCLUSIVE)
    return _report(cluster,image)
